Bindings.Binding:
if ( keystate == "down" ) then
  KU_FixML_Left = true;
else
  KU_FixML_Left = false;
  if(KU_MustToggleMouseLook and GEMSystem_Schedule and not KU_FixML_Right)
  then
    GEMSystem_Schedule(0.1,KU_ToggleMouseLook);
  end
end

if ( keystate == "down" ) then
  KU_FixML_Right = true;
else
  KU_FixML_Right = false;
  if(KU_MustToggleMouseLook and GEMSystem_Schedule and not KU_FixML_Left)
  then
    GEMSystem_Schedule(0.1,KU_ToggleMouseLook);
  end
end
